use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-modal-scalar-census");let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let a=read("/tmp/zopro-grouping-module/native/candidate/artifacts.json");let mut pins=BTreeMap::new();for(n,h)in m["source_files_sha256"].as_object().unwrap(){let p=Path::new("/home/ubuntu/src/zk-tools/zopro").join(n);assert_eq!(hash(&p),h.as_str().unwrap());pins.insert(p.to_str().unwrap().to_owned(),hash(p));}
 for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),hash(p));}
 let mut cases=vec![];for shape in ["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1","merge-54x1"]{let stem=if let Some(s)=shape.strip_prefix("merge-"){format!("merge_{}",s.replace('x',"_"))}else{format!("transfer_confidential_{}",shape.replace('x',"_"))};let key=format!("/tmp/zopro-keys/{stem}.zopro");let fixture=if shape.starts_with("merge-"){shape.to_owned()}else{format!("transfer-{shape}")};let request=format!("/home/ubuntu/src/zk-tools/zopro/tools/zolana/fixtures/{fixture}.json");for p in [&key,&request]{pins.insert(p.clone(),hash(p));}cases.push(json!({"shape":shape,"key":key,"request":request}));}
 fs::write(r.join("cases.json"),serde_json::to_vec_pretty(&cases).unwrap()).unwrap();for name in ["experiment.json","probe.rs","prepare.rs","cases.json","implement.rs","stats.rs.txt"]{let p=r.join(name);pins.insert(p.to_str().unwrap().into(),hash(&p));}
 let mut argv=vec![json!("rustc"),json!("--edition=2021"),json!("-O"),json!("-C"),json!("target-cpu=native"),json!("-C"),json!("lto=off"),json!("-C"),json!("codegen-units=1"),json!("-L"),json!("dependency=/tmp/zopro-grouping-module/target-native/release/deps")];for name in ["zopro_prover","zopro_zolana","zopro_bn254","rayon","serde_json"]{let path=a["libraries"][name].as_str().unwrap();argv.push(json!("--extern"));argv.push(json!(format!("{name}={path}")));}argv.extend([json!(r.join("probe.rs")),json!("-o"),json!(r.join("probe"))]);fs::write(r.join("input-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let steps=json!([{"kind":"command","name":"link","argv":argv,"timeout_seconds":600},{"kind":"command","name":"census","argv":[r.join("probe"),r.join("cases.json")],"timeout_seconds":1200}]);
 let mut env=m["environment"].clone();assert!(env.is_object());env["RAYON_NUM_THREADS"]=json!("32");fs::write(r.join("plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r.join("input-pins.json"),"environment":env,"steps":steps})).unwrap()).unwrap();println!("Frozen{}pins,9keys/fixtures, currentacceptedlibrarylink; no candidatechanges",pins.len());}
